package com.vidyavedika.notification_service.service; import com.vidyavedika.notification_service.dto.*; import com.vidyavedika.notification_service.entity.*; import com.vidyavedika.notification_service.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class NotificationService {private final NotificationRepository r; public NotificationService(NotificationRepository r){this.r=r;} public Notification send(NotificationRequest x){Notification n=new Notification();n.setUserId(x.userId());n.setTitle(x.title());n.setMessage(x.message());return r.save(n);} public List<Notification> list(Long u){return r.findByUserIdOrderByCreatedAtDesc(u);} public Notification markRead(Long id){Notification n=r.findById(id).orElseThrow();n.setReadFlag(true);return r.save(n);}}
